#!/data/data/com.termux/files/usr/bin/bash
# 1102 — стоп-флаг снят по слову владельца 07.11 («подтверждаю»); чтение zalogzaym — первый чат, аккуратно.
echo "== 1102: чтение zalogzaym =="
ssh -o BatchMode=yes -o ConnectTimeout=25 root@45.152.198.192 '
echo "-- 0. стоп-флаг (слово владельца 07.11) --"
rm -f /root/kord-linza/STOP && echo "STOP снят" || echo "STOP не найден"
echo "-- 1. читалка одного чата: zalogzaym, до 70 постов --"
echo "" | base64 -d > /root/kord-glubina/read-one-r1102.py
timeout 120 /root/kord-linza/venv/bin/python /root/kord-glubina/read-one-r1102.py 2>&1 | tail -90
echo "-- 2. пуш в приватный дом --"
cd /root/kord-glubina/kordinaps-machine || exit 1
git pull --rebase -q origin main 2>&1 | tail -1
git add "проекты/ЧТЕНИЕ-zalogzaym-2026-11-07.md" 2>/dev/null
git commit -q -m "ЧТЕНИЕ zalogzaym 07.11 (по слову владельца)" && echo "коммит: ок" || echo "нет изменений"
git push -q origin main 2>&1 | tail -1 && echo "пуш: ок" || echo "пуш: не прошёл"
'
echo "== 1102: конец =="
